func BenchmarkLookupNoReset(b *testing.B) {
	b.ReportAllocs()
	idx := buildTodoIndex(100_000) // inside the timed region
	for i := 0; i < b.N; i++ {
		_ = idx[i%100_000]
	}
}

func BenchmarkLoadTodos(b *testing.B) {
	b.ReportAllocs()
	for b.Loop() {
		loadTodos("testdata/todo.json")
	}
}

func BenchmarkWork(b *testing.B) {
	for i := 0; i < b.N; i++ {
		b.StopTimer()
		x := prepare(i)
		b.StartTimer()
		sink += work(x)
	}
}
